\[\tag{P}\label{eq:P}
	\minimize_{x\in\R^n}\varphi(x)\coloneqq f(x)+g(x),
\]

\begin{ass}
		The following hold in problem \eqref{eq:P}:
		\begin{enumeratass}
		\item\label{ass:f}%
			\(\func{f}{\R^n}{\R}\) has locally Lipschitz-continuous gradient.
		\item\label{ass:g}%
			\(\func{g}{\R^n}{\R\cup\set\infty}\) is proper, lsc, and \(\gamma_g\)-prox-bounded.
		\item\label{ass:phi}%
			\(\inf\varphi>-\infty\).
		\end{enumeratass}
	\end{ass}

				With \(\R\) and \(\Rinf\coloneqq\R\cup\set\infty\) we denote the real and extended-real line, and by \(\N=\set{0,1,\dots}\) the set of natural numbers.
The effective domain of an extended-real-valued function \(\func{h}{\R^n}{\Rinf}\) is denoted by \(\dom h\coloneqq\set{x\in\R^n}[h(x)<\infty]\), and we say that \(h\) is: proper if \(\dom h\neq\emptyset\); lower semicontinuous (lsc) if \(h(\bar x)\leq\liminf_{x\to\bar x}h(x)\) for all \(\bar x\in\R^n\); coercive if \(h(x)\to\infty\) as \(\|x\|\to\infty\).
For $\alpha\in\R$, the $\alpha$-\emph{sublevel set} of $h$ is $\lev_{\leq\alpha} h \coloneqq \set{x\in\R^n : h(x) \leq \alpha}$.


Given a parameter value \(\gamma>0\), the \emph{Moreau envelope} function \(h^\gamma\) and the \emph{proximal mapping} \(\prox_{\gamma h}\) are defined by
\begin{align}
	\label{eq:moreauenvelope}
	h^\gamma(x)
	{}\coloneqq{} &
	\inf_{z\in\R^n}\set{
		h(z)
		{}+{}
		\tfrac{1}{2\gamma}\|z-x\|^2
	} ,
	\\
	\label{eq:proxoperator}
	\prox_{\gamma h}(x)
	{}\coloneqq{} &
	\argmin_{z\in\R^n}\set{
		h(z)
		{}+{}
		\tfrac{1}{2\gamma}\|z-x\|^2
	},
\end{align}
% Prox-boundedness
and we say that \(h\) is \emph{prox-bounded} if it is proper and \(h + \tfrac{1}{2\gamma}\|\cdot\|^2\) is bounded below on \(\R^n\) for some \(\gamma>0\).
The supremum of all such \(\gamma\) is the threshold \(\gamma_h\) of prox-boundedness for \(h\).


				Given a point \(x \in \R^n\), one iteration of the proximal gradient (PG) method for problem \eqref{eq:P} consists in selecting
\begin{equation}\label{eq:FBSiter}
	\def\iter{}
	\bar x
	{}\in{}
	\T(x)
	{}\coloneqq{}
	\FB{x},
\end{equation}

where \(\gamma\in(0,\gamma_g)\) is a stepsize parameter.


\begin{defin}[forward-backward envelope]%
	\begin{subequations}\label{subeq:FBE}%
		Relative to \eqref{eq:P}, the FBE with stepsize \(\gamma\in(0,\gamma_g)\) is
		\begin{align}
		\label{eq:FBE}
			\FBE(x)
		{}\coloneqq{} &
			\min_{w\in\R^n}\set{
				f(x)
				{}+{}
				\innprod{\nabla f(x)}{w-x}
				{}+{}
				g(w)
				{}+{}
				\tfrac{1}{2\gamma}\|w-x\|^2
			}
		\\
		\label{eq:FBEMoreau}
		{}={} &
			f(x)
			{}-{}
			\tfrac\gamma2\|\nabla f(x)\|^2
			{}+{}
			g^\gamma(\Fw x)
		\shortintertext{%
			or, equivalently, letting \(\bar x\) be any element of \(\T(x)\),
		}
		\label{eq:FBEmin}
		{}={} &
			f(x)
			{}+{}
			\innprod{\nabla f(x)}{\bar x-x}
			{}+{}
			g(\bar x)
			{}+{}
			\tfrac{1}{2\gamma}\|\bar x-x\|^2.
		\end{align}
	\end{subequations}
\end{defin}

\begin{algorithm}[tb!]
	\caption{\panoc+: the ``good'' adaptive \(\gamma\)-stepsize rule}%
	\label{alg:PANOC+}%
	\begin{algorithmic}[1]%
\linespread{1.4}\selectfont%
%
%
%
\Require
	\(x^0\in\R^n\);~~
	\(\gamma_0\in(0,\gamma_g)\);~~
	\(D\geq0\);~~
	\(\alpha,\beta\in(0,1)\)%
\Initialize
	\(k\gets0\),~~
	and start from \cref{state:PANOC+:barx}
%
%
\vspace*{1ex}%
\hrule
\vspace*{1ex}%
%
%
%
\def\iter{k}%
%
%
%
	\State
		\label{state:PANOC+:init}%
		\(\gamma_k\gets\gamma_{k-1}\)
	\State
		\label{state:PANOC+:d}%
		Select an update direction \(d^k\in\R^n\) with \(\|d^k\|\leq D\|\bar x^{k-1}-x^{k-1}\|\) and set \(\tau_k=1\)%
	\State
		\label{state:PANOC+:x+}%
		\(x^k=(1-\tau_k)\bar x^{k-1}+\tau_k(x^{k-1}+d^k)\)
	\State
		\label{state:PANOC+:barx}%
		Compute \(\bar x^k\in\T(x^k)\)
		and use it to evaluate \(\Phi_k\coloneqq\FBE(x^k)\) as in \eqref{eq:FBEmin}%
	\If{
		\(
			f(\bar x^k)
		{}>{}
			f(x^k)
			{}+{}
			\innprod{\nabla f(x^k)}{\bar x^k-x^k}
			{}+{}
			\tfrac{\alpha}{2\gamma_k}\|\bar x^k-x^k\|^2
		\)
	}%
	\label{state:PANOC+:gammaLS}%
		\Statex*%
			\(\gamma_k\gets\nicefrac{\gamma_k}{2}\),~
			and go back to \cref{state:PANOC+:d} if \(k>0\), or \cref{state:PANOC+:barx} if \(k=0\)
	\EndIf
	\If{ \(k>0\) ~{\sc and}~ \(
		\Phi_k
		{}>{}
		\Phi_{k-1}
		{}-{}
		\beta\tfrac{1-\alpha}{2\gamma_{k-1}}
		\|\bar x^{k-1}-x^{k-1}\|^2
	\) }\label{state:PANOC+:tauLS}%
		\Statex*
			\(\tau_k\gets\nicefrac{\tau_k}{2}\)~
			and go back to \cref{state:PANOC+:x+}
	\EndIf
	\State
		\(k\gets k+1\)~
		and start the next iteration at \cref{state:PANOC+:init}
\end{algorithmic}
%
\end{algorithm}

\begin{rem}[Algorithm notation]\label{rem:notation}%
	\Cref{alg:PANOC+} operates two linesearch steps within each iteration, one on the ``proximal'' stepsize \(\gamma_k\) at \cref{state:PANOC+:gammaLS} and one on the ``direction'' stepsize \(\tau_k\) at \cref{state:PANOC+:tauLS}.
	Whenever the respective needed conditions are violated, either \(\gamma_k\) or \(\tau_k\) is reduced and the iteration restarted from a previous step.
	As a consequence, variables may be \emph{overwritten} within each iteration before being accepted.
	To avoid a heavy double-index notation, used only within proofs out of full rigor, the sub- and superscript notation is designed to differentiate temporary and permanent variables; specifically, within iteration \(k\) only variables indexed with \(k\) are updated, whereas those indexed with \(k-1\) remain untouched.
	Similar considerations apply to \cref{alg:PANOC}.
\end{rem}

\begin{align}\label{eq:L}
		\LL_\beta(x,z,y)
	{}\coloneqq{} &
		f(x)+g(z)+\innprod{y}{x-z}+\tfrac\beta2\|x-z\|^2,
	\shortintertext{we remark that}\label{eq:L:FBE}
		\FBE(x)
	{}={} &
		\LL(x,\bar x,-\nabla f(x)),
	\shortintertext{where}\label{eq:L:barx}
		\bar x
	{}\in{} &
		\T(x)
		{}={}
		\argmin\LL(x,{}\cdot{},-\nabla f(x))
	\end{align}

\begin{algorithmic}[1]%
	\makeatletter
		\renewcommand{\alglinenumber}[1]{\footnotesize\fillwidthof[l]{\oldstylenums{88}:}{{\bf 2}.4$'$:}~}%
		\renewcommand{\theALG@line}{2.\oldstylenums{4}$'$}%
	\makeatother
	\State\label{state:NoProx:barx}%
		Let \(\bar x^k\) be a suboptimal minimizer of \(\LL(x^k,{}\cdot{},-\nabla f(x^k))\) such that
		\begin{equation}\label{eq:prox:better}
			\Phi_k
		{}\coloneqq{}
			\LL(x^k,\bar x^k,-\nabla f(x^k))
		{}\leq{}
			\LL(x^k,\bar x^{k-1},-\nabla f(x^k)).
		\end{equation}
	\end{algorithmic}

To avoid trivialities, in what follows we assume that \(x^k\neq\bar x^k\) always holds.

