\begin{lem}\label{thm:inexact:lb}%
	Let a constant \(c\in\R\), a sequence \(\seq{\gamma_j}[j\in\N]\searrow0\), and two bounded sequences \(\seq{u^j,z^j}[j\in\N]\) in \(\R^n\) be fixed, and for every \(j\in\N\) let \(\bar z^j\) be such that
	\[
		g(\bar z^j)+\innprod*{u^j}{\bar z^j-z^j}+\tfrac{1}{2\gamma_j}\|\bar z^j-z^j\|^2
		{}\leq{}
		\tfrac{c}{2\gamma_j}.
	\]
	Then, \(\seq{\bar z^j}[j\in\N]\) is bounded.
	\begin{proof}
		An application of Young's inequality on the inner product yields
		\[
		2\gamma_jg(\bar z^j)
		{}\leq{}
		c
		{}+{}
		\gamma_j\|u_j\|^2
		{}-{}
		(1-\gamma_j)\|\bar z^j-z^j\|^2.
		\]
		To arrive to a contradiction, up to extracting if necessary, suppose that \(0<\|\bar z^j\|\to\infty\).
		Since \(\liminf_{j\to\infty}{g(\bar z^j)}/{\|\bar z^j\|^2}>-\infty\) by \cite[Ex. 1.24]{rockafellar1998variational}, dividing by \(\|\bar z^j\|^2\) and passing to the limit leads to the contradiction \(0\leq -1\).
	\end{proof}
\end{lem}

\begin{lem}[Well definedness of the ``good'' (inexact) \panoc+]\label{thm:PANOC+:finite}%
	Consider the iterates generated by \cref{alg:PANOC+} with inexact proximal evaluation at \cref{state:PANOC+:barx} as given in \eqref{eq:prox:better}.
	The following hold:
	\begin{enumerate}
	\item\label{thm:finite:LS}%
		Well definedness: at every iteration, the number of backtrackings at \cref{state:PANOC+:gammaLS,state:PANOC+:tauLS} is finite.
	\item\label{thm:finite:descent}%
		At the end of the \(k\)-th iteration (\(k\geq1\)), one has
		\begin{equation}\label{eq:SD}
				\varphi(\bar x^k)
				{}+{}
				\delta_k
			{}\leq{}
				\Phi_k
			{}\leq{}
				\def\iter{k-1}
				\Phi_{k-1}
				{}-{}
				\beta\delta_{k-1}
			\quad\text{where}\quad
				\delta_k
			{}\coloneqq{}
				\tfrac{1-\alpha}{2\gamma_k}
				\|\bar x^k-x^k\|^2.
			\end{equation}
	\item\label{thm:finite:sublevel}%
		Every iterate \(\bar x^k\) remains within \(\lev_{\leq c}\varphi\), where \(c=\Phi_0<\infty\).
	\end{enumerate}
	\begin{proof}
		As observed in \cref{rem:notation}, each iteration \(k\) defines or updates only variables indexed with a \(k\) sub/superscript, while those defined in previous iterations are untouched.
		In what follows, let us index by \({k,j}\) the variables defined at the \(j\)-th attempt within iteration \(k\).
		Note further that \(\gamma_{k,j}L_{k,j}=\alpha\in(0,1)\) holds for every attempt \(j\) within every iteration \(k\), since every time \(\gamma_k\) is halvened the estimate \(L_k\) is doubled (cf. \cref{state:PANOC+:gammaLS}).
		\begin{proofitemize}
		\item\ref{thm:finite:LS}~
			We proceed by induction on \(k\).
			If \(k=0\), there is no backtracking on \(\tau\), and from \cref{thm:inexact:lb} we conclude that all the trials \(\bar x^{0,j}\) remain confined in a bounded set \(\Omega_0\), and therefore any stepsize \(\gamma_{0,j}<\nicefrac{1}{L_{f,\Omega_0}}\) is accepted.

			Suppose now that \(k>0\) and observe that, by the definition of \(\Phi_k\) in \eqref{eq:prox:better} and the failure of the condition at \cref{state:PANOC+:gammaLS}, the inequality
			\begin{equation}\label{eq:lphi}
				\varphi(\bar x^{k-1})
				{}\leq{}
				\Phi_{k-1}
				{}-{}
				\tfrac{1-\alpha}{2\gamma_{k-1}}\|x^{k-1}-\bar x^{k-1}\|^2
			\end{equation}
			holds.
			Since \(\|d^{k,j}\|\leq D\|\bar x^{k-1}-x^{k-1}\|\) and \(\tau_{k,j}\in[0,1]\), any attempt \(x^{k,j}\) defined at \cref{state:PANOC+:x+} during the \(k\)-th iteration satisfies
			\[
				\|x^{k,j}-\bar x^{k-1}\|
			{}={}
				\tau_{k,j}\|
					x^{k-1}-\bar x^{k-1}
					{}+{}
					d^{k,j}
				\|
			{}\leq{}
				(1+D)\|\bar x^{k-1}-x^{k-1}\|
			\]
			and thus remains in a bounded set, be it \(\Omega_k\).
			To arrive to a contradiction, suppose that \(\gamma_{k,j}\searrow0\) as \(j\to\infty\).
			Observe that condition \eqref{eq:prox:better} reads
			\begin{Align*}
				g(\bar x^{k,j})
				{}+{}
				\innprod*{\nabla f(x^{k,j})}{\bar x^{k,j}-\bar x^{k-1}}\quad
			&
			\\
				{}+{}
				\tfrac{1}{2\gamma_{k,j}}\|x^{k,j}-\bar x^{k,j}\|^2
			& {}\leq{}
				g(\bar x^{k-1})
				{}+{}
				\tfrac{1}{2\gamma_{k,j}}\|x^{k,j}-\bar x^{k-1}\|^2.
			\end{Align*}
			Since \(\seq{x^{k,j}}[j\in\N]\) is bounded, an application of \cref{thm:inexact:lb} reveals that \(\seq{\bar x^{k,j}}\) too is bounded.
			Up to possibly enlarging the set, both sequences remain confined in the bounded set \(\Omega_k\), implying that the condition at \cref{state:PANOC+:gammaLS} should have terminated in finite time, whence the sought contradiction.

			Hence, \(\gamma_{k,j}\) is backtracked finitely many times within iteration \(k\);
			up to discarding early attempts, we may denote \(\gamma_{k,j}=\gamma_k\).
			Condition \eqref{eq:prox:better} reads
			\begin{align*}
				\LL(x^{k,j},\bar x^{k,j},-\nabla f(x^{k,j}))
			{}\leq{} &
				\LL(x^{k,j},\bar x^{k-1},-\nabla f(x^{k,j}))
			\\
			{}={} &
				f(x^{k,j})+g(\bar x^{k-1})+\innprod*{\nabla f(x^{k,j})}{\bar x^{k-1}-x^{k,j}}
			\\
			&
				{+{}}\tfrac{1}{2\gamma}\|x^{k,j}-\bar x^{k-1}\|^2.
			\end{align*}
			As \(\tau_{k,j}\searrow0\), one has that \(x^{k,j}\to\bar x^{k-1}\).
			Since \(f\) and \(\nabla f\) are continuous, the right-hand side of the inequality converges to \(\varphi(\bar x^{k-1})\), overall resulting in
			\[
			\limsup_{j\to\infty}\LL(x^{k,j},\bar x^{k,j},-\nabla f(x^{k,j}))
			{}\leq{}
			\varphi(\bar x^{k-1})
			{}\overrel[\leq]{\eqref{eq:lphi}}{}
			\Phi_{k-1}-\tfrac{1-\alpha}{2\gamma_{k-1}}\|x^{k-1}-\bar x^{k-1}\|^2.
			\]
			Since \(\|x^{k-1}-\bar x^{k-1}\|>0\) and \(\beta<1\), for \(j\) large enough the condition at \cref{state:PANOC+:tauLS} will be violated and therefore the \(k\)-th iteration successfully terminated.
		%%
		%%
		\item\ref{thm:finite:descent}
			Follows by combining \eqref{eq:lphi} with the failure of the condition at \cref{state:PANOC+:tauLS} at the end of the iteration.
		\item\ref{thm:finite:sublevel}~
			Direct consequence of assertion \ref{thm:finite:descent}.
		\qedhere
		\end{proofitemize}
	\end{proof}
\end{lem}

\begin{proof}
		\begin{proofitemize}
		\item\ref{thm:PANOC+:asymp:cost}~
			Follows from \eqref{eq:SD}.
		\item\ref{thm:PANOC+:asymp:summable}~
			A telescoping argument on \eqref{eq:SD} yields
			\begin{equation}\label{eq:summable}
				\beta(1-\alpha)
				\sum_{k\in\N}{
					\tfrac{1}{2\gamma_k}
					\|\bar x^k-x^k\|^2
				}
			{}\leq{}
				\Phi_0
				{}-{}
				\inf\varphi
			{}={}
				\def\iter{0}
				\FBE(x^0)-\inf\varphi,
			\end{equation}
			whence the claimed finite sum.
	%%%%
	%%%%
	%%%%
		\item\ref{thm:PANOC+:asymp:fpr}~
			That \(\|x^k-\bar x^k\|\to0\) follows from assertion \ref{thm:PANOC+:asymp:summable}, since \(\gamma_k\) is upper bounded.
			Next, by the conditions at \cref{state:PANOC+:x+,,state:PANOC+:d}, observe that
			\begin{align*}
			\numberthis\label{eq:xkdiff}
				\|x^k-x^{k-1}\|
			{}={} &
				\bigl\|
					(1-\tau_k)(\bar x^{k-1}-x^{k-1})
					{}+{}
					\tau_kd^k
				\bigr\|
			{}\leq{}
				(1+D)\|\bar x^{k-1}-x^{k-1}\|
			\shortintertext{and thus \(\|x^k-x^{k-1}\|\) vanishes, and in turn so does \(\|\bar x^k-\bar x^{k-1}\|\) since}
				\|\bar x^k-\bar x^{k-1}\|
			{}\leq{} &
				\|x^k-\bar x^k\|
				{}+{}
				\|\bar x^{k-1}-x^{k-1}\|
				{}+{}
				\|x^k-x^{k-1}\|.
			\end{align*}
		\item\ref{thm:PANOC+:asymp:gammaconstant}~
			The first implication follows from \cref{thm:finite:sublevel}, and the second one from assertion \ref{thm:PANOC+:asymp:summable}.
			If \(\seq{x^k}\) is bounded, and thus so is \(\seq{\bar x^k}\), the set \(\Omega_k\) in the proof of \cref{thm:finite:LS} can be taken independent of \(k\), and asymptotic constancy of \(\gamma_k\) follows from the same arguments therein.
			Finally, if \(\nabla f\) is $L_f$-Lipschitz continuous the condition at \cref{state:PANOC+:gammaLS} fails to hold as soon as $\gamma_k\leq\nicefrac{\alpha}{L_f}$ \cite[Prop. A.24]{bertsekas1999nonlinear}, and \(\gamma_k\) is thus asymptotically constant.
	%%%%
	%%%%
